result:
Here's Orb Rush, a single-file canvas game. You move with the arrow keys, WASD, or the mouse/touch. Collect the orbs, dodge the spikes, and reach 300 points to win.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Orb Rush</title>
<style>
  html, body { margin: 0; height: 100%; background: #05060f; overflow: hidden; }
  body { display: flex; align-items: center; justify-content: center; }
  canvas {
    width: min(96vw, calc(90vh * 0.75));
    height: auto;
    aspect-ratio: 3 / 4;
    display: block;
    background: #0a0c1f;
    border: 2px solid #2a3a5a;
    border-radius: 10px;
    box-shadow: 0 0 36px rgba(90, 220, 255, 0.25);
    cursor: crosshair;
    touch-action: none;
    user-select: none;
  }
</style>
</head>
<body>
<canvas id="c" width="480" height="640"></canvas>
<script>
(() => {
  'use strict';

  const W = 480, H = 640, WIN_SCORE = 300;
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');

  // ---------- state ----------
  let state = 'menu';            // 'menu' | 'playing' | 'over' | 'won'
  let score = 0, best = 0, time = 0;
  let player = { x: W / 2, y: H - 100, r: 13 };
  let orbs = [], hazards = [], particles = [];
  let spawnOrbT = 0, spawnHazT = 0;
  let overAt = 0;
  let pointerActive = false, px = W / 2, py = H - 100;
  const keys = {};
  const stars = Array.from({ length: 70 }, () => ({
    x: Math.random() * W, y: Math.random() * H, z: 0.2 + Math.random() * 0.8
  }));

  // ---------- test hook (keep in sync) ----------
  function sync() { window.gameState = { score: score, state: state }; }
  function setState(s) { state = s; sync(); }
  function addScore(n) { score += n; if (score > best) best = score; sync(); }
  sync();

  // ---------- audio (generated with WebAudio, no files) ----------
  let actx = null;
  function ensureAudio() {
    if (!actx) {
      try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { actx = null; }
    }
    if (actx && actx.state === 'suspended') actx.resume();
  }
  function beep(freq, dur, type = 'square', vol = 0.06, slide = 0) {
    if (!actx) return;
    const t = actx.currentTime;
    const o = actx.createOscillator(), g = actx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(actx.destination);
    o.start(t);
    o.stop(t + dur + 0.02);
  }

  // ---------- helpers ----------
  function difficulty() { return 1 + Math.min(time / 40, 2); }   // 1x -> 3x
  function level() { return 1 + Math.floor(time / 15); }

  function burst(x, y, c, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, s = 40 + Math.random() * 180;
      const life = 0.4 + Math.random() * 0.5;
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life, max: life, c, size: 2 + Math.random() * 2 });
    }
  }

  function glow(x, y, r, c, a = 1) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r * 3);
    g.addColorStop(0, `rgba(${c},${a})`);
    g.addColorStop(0.3, `rgba(${c},${a * 0.45})`);
    g.addColorStop(1, `rgba(${c},0)`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r * 3, 0, Math.PI * 2);
    ctx.fill();
  }

  // ---------- spawning ----------
  function makeOrb() {
    const gold = Math.random() < 0.15;
    return {
      x: 30 + Math.random() * (W - 60), y: -15,
      r: gold ? 11 : 9,
      vy: 60 + Math.random() * 40,
      phase: Math.random() * Math.PI * 2,
      gold, value: gold ? 25 : 10,
      color: gold ? '255,215,90' : '120,255,160'
    };
  }

  function makeHazard() {
    const d = difficulty();
    const h = { r: 15, rot: Math.random() * 6.28, spin: (Math.random() < 0.5 ? -1 : 1) * (2 + Math.random() * 3), vx: 0, vy: 0 };
    if (time > 25 && Math.random() < 0.4) {          // sideways sweepers after 25s
      const fromLeft = Math.random() < 0.5;
      h.x = fromLeft ? -18 : W + 18;
      h.y = 80 + Math.random() * (H - 260);
      h.vx = (fromLeft ? 1 : -1) * (60 + d * 25);
    } else {                                         // falling spikes
      h.x = 30 + Math.random() * (W - 60);
      h.y = -20;
      h.vy = 110 + d * 35 + Math.random() * 40;
    }
    return h;
  }

  // ---------- game flow ----------
  function resetGame() {
    score = 0; time = 0;
    player = { x: W / 2, y: H - 100, r: 13 };
    px = player.x; py = player.y;
    orbs = []; hazards = []; particles = [];
    spawnOrbT = 0; spawnHazT = 1.0;
    sync();
  }

  function startGame() {
    ensureAudio();
    resetGame();
    setState('playing');
    beep(660, 0.12, 'triangle', 0.08, 300);
  }

  function die() {
    burst(player.x, player.y, '255,77,109', 40);
    beep(220, 0.5, 'sawtooth', 0.12, -180);
    overAt = performance.now();
    setState('over');
  }

  function win() {
    beep(523, 0.15, 'triangle', 0.1);
    setTimeout(() => beep(784, 0.3, 'triangle', 0.1), 120);
    overAt = performance.now();
    setState('won');
  }

  function action() {
    ensureAudio();
    if (state === 'menu') startGame();
    else if ((state === 'over' || state === 'won') && performance.now() - overAt > 600) startGame();
  }

  // ---------- update ----------
  function update(dt) {
    time += dt;
    const d = difficulty();

    // movement: keyboard takes priority, otherwise follow the pointer
    let mx = 0, my = 0;
    if (keys.ArrowLeft || keys.KeyA) mx--;
    if (keys.ArrowRight || keys.KeyD) mx++;
    if (keys.ArrowUp || keys.KeyW) my--;
    if (keys.ArrowDown || keys.KeyS) my++;
    const sp = 330;
    if (mx || my) {
      const l = Math.hypot(mx, my);
      player.x += mx / l * sp * dt;
      player.y += my / l * sp * dt;
      px = player.x; py = player.y;
    } else if (pointerActive) {
      const dx = px - player.x, dy = py - player.y, dist = Math.hypot(dx, dy);
      if (dist > 1) {
        const s = Math.min(dist, sp * 1.5 * dt);
        player.x += dx / dist * s;
        player.y += dy / dist * s;
      }
    }
    player.x = Math.max(player.r, Math.min(W - player.r, player.x));
    player.y = Math.max(player.r, Math.min(H - player.r, player.y));

    // trail
    if (Math.random() < 0.6) {
      particles.push({ x: player.x, y: player.y, vx: (Math.random() - 0.5) * 20, vy: 10 + Math.random() * 20,
        life: 0.35, max: 0.35, c: '90,220,255', size: 3 });
    }

    // spawn timers (intervals shrink as time passes)
    spawnOrbT -= dt;
    if (spawnOrbT <= 0) {
      orbs.push(makeOrb());
      spawnOrbT = Math.max(0.5, 0.8 - time * 0.004) * (0.7 + Math.random() * 0.6);
    }
    spawnHazT -= dt;
    if (spawnHazT <= 0) {
      hazards.push(makeHazard());
      spawnHazT = Math.max(0.28, 1.3 - time * 0.02) * (0.7 + Math.random() * 0.6);
    }

    // orbs
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      o.phase += dt * 4;
      o.y += o.vy * dt;
      o.x += Math.sin(o.phase) * 20 * dt;
      if (Math.hypot(o.x - player.x, o.y - player.y) < player.r + o.r + 3) {
        addScore(o.value);
        burst(o.x, o.y, o.color, 14);
        beep(o.gold ? 1320 : 660, 0.09, 'sine', 0.08, o.gold ? 400 : 250);
        orbs.splice(i, 1);
        if (score >= WIN_SCORE) { win(); return; }
      } else if (o.y > H + 20) {
        orbs.splice(i, 1);
      }
    }

    // hazards
    for (let i = hazards.length - 1; i >= 0; i--) {
      const h = hazards[i];
      h.x += h.vx * dt;
      h.y += h.vy * dt;
      h.rot += h.spin * dt;
      if (Math.hypot(h.x - player.x, h.y - player.y) < player.r + h.r * 0.7) { die(); return; }
      if (h.y > H + 40 || h.x < -40 || h.x > W + 40) hazards.splice(i, 1);
    }
    void d;
  }

  function updateParticles(dt) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 0.96;
      p.vy *= 0.96;
      p.life -= dt;
      if (p.life <= 0) particles.splice(i, 1);
    }
  }

  // ---------- drawing ----------
  function drawTitle(text, y, color, size) {
    ctx.font = `bold ${size}px monospace`;
    ctx.fillStyle = color;
    ctx.shadowColor = color;
    ctx.shadowBlur = 24;
    ctx.fillText(text, W / 2, y);
    ctx.shadowBlur = 0;
  }

  function drawOverlay() {
    ctx.fillStyle = 'rgba(5,6,15,0.72)';
    ctx.fillRect(0, 0, W, H);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const blink = Math.floor(performance.now() / 500) % 2 === 0;
    const canContinue = performance.now() - overAt > 600;

    if (state === 'menu') {
      drawTitle('ORB RUSH', 170, '#7dffb0', 46);
      ctx.font = '15px monospace';
      ctx.fillStyle = '#bcd';
      const lines = [
        'Move: Arrow keys / WASD',
        'or move the mouse / finger',
        '',
        'Collect glowing orbs  (+10, gold +25)',
        'Avoid the red spikes!',
        'Spikes get faster and more numerous.',
        `Reach ${WIN_SCORE} points to win.`
      ];
      lines.forEach((t, i) => ctx.fillText(t, W / 2, 260 + i * 26));
      if (blink) {
        ctx.fillStyle = '#ffe16b';
        ctx.font = 'bold 18px monospace';
        ctx.fillText('Press ENTER / SPACE or click to start', W / 2, 500);
      }
    } else if (state === 'over') {
      drawTitle('GAME OVER', 220, '#ff6b86', 44);
      ctx.font = 'bold 22px monospace';
      ctx.fillStyle = '#cfe';
      ctx.fillText(`Score: ${score}`, W / 2, 290);
      ctx.fillText(`Best: ${best}`, W / 2, 322);
      if (canContinue && blink) {
        ctx.fillStyle = '#ffe16b';
        ctx.font = 'bold 18px monospace';
        ctx.fillText('Press ENTER / SPACE or click to retry', W / 2, 410);
      }
    } else if (state === 'won') {
      drawTitle('YOU WIN!', 220, '#ffd75a', 46);
      ctx.font = 'bold 22px monospace';
      ctx.fillStyle = '#cfe';
      ctx.fillText(`Score: ${score}`, W / 2, 290);
      ctx.fillText(`Best: ${best}`, W / 2, 322);
      if (canContinue && blink) {
        ctx.fillStyle = '#ffe16b';
        ctx.font = 'bold 18px monospace';
        ctx.fillText('Press ENTER / SPACE or click to play again', W / 2, 410);
      }
    }
  }

  function draw() {
    // background
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#0a0c1f';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#8af';
    for (const s of stars) {
      ctx.globalAlpha = 0.25 + s.z * 0.5;
      ctx.fillRect(s.x, s.y, s.z * 2, s.z * 2);
    }
    ctx.globalAlpha = 1;

    // glowing layer
    ctx.globalCompositeOperation = 'lighter';
    const t = performance.now() / 1000;

    for (const o of orbs) {
      const pulse = 1 + Math.sin(t * 6 + o.phase) * 0.12;
      glow(o.x, o.y, o.r * pulse, o.color, 0.9);
      ctx.fillStyle = 'rgba(255,255,255,0.95)';
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r * 0.45, 0, Math.PI * 2);
      ctx.fill();
    }

    for (const h of hazards) {
      glow(h.x, h.y, h.r * 0.8, '255,70,100', 0.5);
      ctx.save();
      ctx.translate(h.x, h.y);
      ctx.rotate(h.rot);
      ctx.beginPath();
      for (let i = 0; i < 10; i++) {
        const rad = i % 2 ? h.r * 0.45 : h.r;
        const a = i * Math.PI / 5;
        ctx.lineTo(Math.cos(a) * rad, Math.sin(a) * rad);
      }
      ctx.closePath();
      ctx.fillStyle = 'rgba(255,70,100,0.85)';
      ctx.fill();
      ctx.strokeStyle = '#ffb3c1';
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.restore();
    }

    if (state !== 'over') {
      glow(player.x, player.y, player.r, '90,220,255', 0.9);
      ctx.beginPath();
      ctx.arc(player.x, player.y, player.r * 0.6, 0, Math.PI * 2);
      ctx.fillStyle = '#e8fbff';
      ctx.fill();
    }

    for (const p of particles) {
      const a = Math.max(0, p.life / p.max);
      ctx.fillStyle = `rgba(${p.c},${a})`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.5 + a * 0.5), 0, Math.PI * 2);
      ctx.fill();
    }

    // HUD and overlays
    ctx.globalCompositeOperation = 'source-over';
    if (state !== 'menu') {
      ctx.textBaseline = 'alphabetic';
      ctx.font = 'bold 22px monospace';
      ctx.fillStyle = '#cfe';
      ctx.textAlign = 'left';
      ctx.fillText(`SCORE ${score}`, 16, 32);
      ctx.textAlign = 'right';
      ctx.fillText(`BEST ${best}`, W - 16, 32);
      ctx.textAlign = 'center';
      ctx.font = '12px monospace';
      ctx.fillStyle = '#89a';
      ctx.fillText(`LEVEL ${level()}   TIME ${Math.floor(time)}s`, W / 2, 32);
      // progress toward win
      ctx.fillStyle = '#223';
      ctx.fillRect(16, 42, W - 32, 6);
      ctx.fillStyle = '#6fa';
      ctx.fillRect(16, 42, (W - 32) * Math.min(1, score / WIN_SCORE), 6);
    }
    if (state !== 'playing') drawOverlay();
  }

  // ---------- loop ----------
  let last = performance.now();
  function frame(now) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    for (const s of stars) {
      s.y += s.z * dt * 25;
      if (s.y > H) { s.y -= H; s.x = Math.random() * W; }
    }
    if (state === 'playing') update(dt);
    updateParticles(dt);
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // ---------- input ----------
  const PREVENT = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'];
  window.addEventListener('keydown', e => {
    if (PREVENT.includes(e.code)) e.preventDefault();
    keys[e.code] = true;
    if (!e.repeat && (e.code === 'Enter' || e.code === 'NumpadEnter' || e.code === 'Space')) action();
  });
  window.addEventListener('keyup', e => { keys[e.code] = false; });
  window.addEventListener('blur', () => { for (const k in keys) keys[k] = false; });

  function toGame(clientX, clientY) {
    const r = canvas.getBoundingClientRect();
    return [(clientX - r.left) / r.width * W, (clientY - r.top) / r.height * H];
  }

  canvas.addEventListener('mousemove', e => {
    [px, py] = toGame(e.clientX, e.clientY);
    pointerActive = true;
  });
  canvas.addEventListener('mouseleave', () => { pointerActive = false; });
  canvas.addEventListener('mousedown', e => {
    [px, py] = toGame(e.clientX, e.clientY);
    pointerActive = true;
    action();
  });
  canvas.addEventListener('touchstart', e => {
    e.preventDefault();
    const t = e.touches[0];
    [px, py] = toGame(t.clientX, t.clientY);
    pointerActive = true;
    action();
  }, { passive: false });
  canvas.addEventListener('touchmove', e => {
    e.preventDefault();
    const t = e.touches[0];
    [px, py] = toGame(t.clientX, t.clientY);
    pointerActive = true;
  }, { passive: false });
  canvas.addEventListener('touchend', e => {
    e.preventDefault();
    pointerActive = false;
  }, { passive: false });
})();
</script>
</body>
</html>
